const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const DATA_FILE = '/data/entries.json';
const PORT = 8080;

function loadEntries() {
  try {
    return JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
  } catch {
    return [];
  }
}

function saveEntries(entries) {
  fs.mkdirSync(path.dirname(DATA_FILE), { recursive: true });
  fs.writeFileSync(DATA_FILE, JSON.stringify(entries, null, 2));
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderPage(entries) {
  const items = entries
    .slice()
    .reverse()
    .map(
      (e) => `
      <li class="entry">
        <div class="entry-header">
          <strong>${escapeHtml(e.name)}</strong>
          <span class="entry-date">${escapeHtml(e.date)}</span>
        </div>
        <p>${escapeHtml(e.message)}</p>
      </li>`
    )
    .join('');

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Guestbook</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 640px; margin: 2rem auto; padding: 0 1rem; color: #222; }
    h1 { margin-bottom: 0.25rem; }
    form { display: flex; flex-direction: column; gap: 0.5rem; margin-bottom: 2rem; }
    input, textarea { font: inherit; padding: 0.5rem; border: 1px solid #ccc; border-radius: 4px; }
    button { font: inherit; padding: 0.5rem; border: none; border-radius: 4px; background: #2563eb; color: white; cursor: pointer; }
    button:hover { background: #1d4ed8; }
    ul { list-style: none; padding: 0; }
    .entry { border-bottom: 1px solid #eee; padding: 0.75rem 0; }
    .entry-header { display: flex; justify-content: space-between; }
    .entry-date { color: #888; font-size: 0.85rem; }
  </style>
</head>
<body>
  <h1>Guestbook</h1>
  <p>Leave a note. Entries survive a restart.</p>
  <form method="POST" action="/">
    <input type="text" name="name" placeholder="Your name" required maxlength="80">
    <textarea name="message" placeholder="Your message" required maxlength="1000" rows="3"></textarea>
    <button type="submit">Sign the guestbook</button>
  </form>
  <ul>${items || '<p>No entries yet &mdash; be the first to sign.</p>'}</ul>
</body>
</html>`;
}

function parseFormBody(body) {
  const params = new URLSearchParams(body);
  return { name: params.get('name') || '', message: params.get('message') || '' };
}

const server = http.createServer((req, res) => {
  if (req.method === 'GET' && req.url === '/') {
    const entries = loadEntries();
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(renderPage(entries));
    return;
  }

  if (req.method === 'POST' && req.url === '/') {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk;
      if (body.length > 1e6) req.destroy();
    });
    req.on('end', () => {
      const { name, message } = parseFormBody(body);
      if (name.trim() && message.trim()) {
        const entries = loadEntries();
        entries.push({
          name: name.trim().slice(0, 80),
          message: message.trim().slice(0, 1000),
          date: new Date().toISOString(),
        });
        saveEntries(entries);
      }
      res.writeHead(303, { Location: '/' });
      res.end();
    });
    return;
  }

  res.writeHead(404, { 'Content-Type': 'text/plain' });
  res.end('Not found');
});

server.listen(PORT, () => {
  console.error(`[guestbook] listening on ${PORT}`);
});

